+
+// ── Import after mocks ──────────────────────────────────────────────────────
+const { triageIssue } = await import("../../src/workers/triageWorker.js");
+
+// ── Fixtures ────────────────────────────────────────────────────────────────
+
+function makeIssuePayload(overrides = {}) {
+  return {
+    payload: {
