+  mockFail.mockResolvedValue({});
+  mockNotifyTriage.mockResolvedValue(null);
+});
+
+// ── Tests ───────────────────────────────────────────────────────────────────
+
+describe("PF-A1-01: triage auto_comment semantics", () => {
+
+  // 1. Normal issue + auto_comment:true → one summary comment
